<h1>دسترسی مدیران</h1><div class="grid2 section"><section class="card"><h2>افزودن مدیر از حساب موجود</h2><?= $this->start('/admins/create') ?><?= $this->field('user_id','شناسه داخلی حساب موجود') ?><?= $this->field('username','شناسه جدید مدیریت') ?><?= $this->field('new_password','رمز اختصاصی مدیر جدید','password') ?><label for="role">نقش</label><select name="role" id="role"><option value="content_admin">مدیر محتوا</option><option value="system_admin">مدیر سامانه</option></select><?= $this->field('current_password','رمز فعلی شما برای تأیید','password') ?><button class="primary">ایجاد دسترسی مدیریت</button></form></section><div class="records"><?php foreach($rows as $row): ?><article class="card"><h2><?= $this->h($row['display_name']) ?></h2><p class="ltr"><?= $this->h($row['username']) ?></p><span class="tag"><?= $row['role']==='system_admin'?'مدیر سامانه':'مدیر محتوا' ?></span><?php if($row['id']!==$this->actor['admin_id']): ?><?= $this->start('/admins/role') ?><input type="hidden" name="id" value="<?= $this->h($row['id']) ?>"><label>نقش تازه<select name="role"><option value="content_admin">مدیر محتوا</option><option value="system_admin">مدیر سامانه</option></select></label><?= $this->field('current_password','رمز فعلی شما','password') ?><button class="secondary">تغییر نقش و ابطال نشست‌های مدیر</button></form><?php endif; ?></article><?php endforeach; ?></div></div>
